async function criarPedido(formData: FormData) {
  'use server'
  const item = formData.get('item')
  await db.pedidos.create({ data: { item } })
  revalidatePath('/pedidos')
}

export default function Form() {
  return <form action={criarPedido}><input name="item" /><button>Enviar</button></form>
}

'use client'
import { useState } from 'react'

export default function Contador() {
  const [count, setCount] = useState(0)
  return <button onClick={() => setCount(count + 1)}>{count}</button>
}

async function Produtos() {
  const res = await fetch('https://api.exemplo.com/produtos', {
    next: { revalidate: 60 },
  })
  const produtos = await res.json()
  return <Lista itens={produtos} />
}

async function publicarPost(id: string) {
  'use server'
  await db.posts.publish(id)
  revalidateTag('posts')
}

export async function GET() {
  const produtos = await db.produtos.findMany()
  return Response.json(produtos)
}

